from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanFixActionStateASMV2(SchemaObject):
    revision = SchemaField(name="revision")
    added_objects = SchemaField(name="added_objects")
    updated_objects = SchemaField(name="updated_objects")
    action_id = SchemaField(name="action_id", not_null=True)
    links = SchemaField(name="links")
    status = SchemaField(name="status", not_null=True)
    error_message = SchemaField(name="error_message")

    def __init__(self, revision, added_objects, updated_objects, action_id, links, status, error_message):
        self.revision = revision
        self.added_objects = added_objects
        self.updated_objects = updated_objects
        self.action_id = action_id
        self.links = links
        self.status = status
        self.error_message = error_message

        super(PlanFixActionStateASMV2, self).__init__()
